"use client"; // 클라이언트 측에서만 실행되도록 명시

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import styles from './Modal.module.css';
import { getMembershipId, getToken } from "../../../token";  // getMembershipId와 getToken을 token.ts에서 가져옴

const Modal = ({ isOpen, onClose }) => {
  const [userInfo, setUserInfo] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isOpen) return;  // 모달이 열릴 때만 실행

    const loadUserData = async () => {
      try {
        const membershipId = getMembershipId();  // getMembershipId로 membershipId를 가져옴
        if (!membershipId) {
          console.error('Membership ID가 존재하지 않습니다.');
          return;
        }

        const jwtToken = await getToken();  // JWT 토큰 가져오기
        if (!jwtToken) {
          console.error('JWT 토큰이 존재하지 않습니다.');
          return;
        }

        // API 호출을 통해 사용자 정보 가져오기
        const response = await axios.get(`https://ec2-3-34-134-27.ap-northeast-2.compute.amazonaws.com/api/users/${membershipId}`, {
          headers: {
            Authorization: `Bearer ${jwtToken}`,  // Authorization 헤더에 JWT 토큰 추가
          },
        });

        setUserInfo(response.data.result);  // 사용자 정보에서 result만 추출하여 저장
      } catch (error) {
        console.error('사용자 정보를 가져오는 데 실패했습니다:', error);
      } finally {
        setLoading(false);
      }
    };

    loadUserData();  // 직접 API 호출
  }, [isOpen]); // 모달이 열릴 때마다 API 호출

  if (!isOpen) return null; // 모달이 닫히면 아무것도 렌더링하지 않음

  return (
    <div className={styles.modalOverlay}>
      <div className={styles.modalContent}>
        <div className={styles.modalHeader}>
          <span className={styles.close} onClick={onClose}>
            &times;
          </span>
          <h2>Modal Header</h2>
        </div>
        <div className={styles.modalBody}>
          {loading ? (
            <p>Loading...</p>
          ) : userInfo ? (
            <>
              <p>User ID: {userInfo.id}</p>
              <p>Nickname: {userInfo.nickname}</p>
              <p>Role: {userInfo.role}</p>
              <p>Account: {userInfo.account}</p>
              <p>Entire Score: {userInfo.entireScore}</p>
              <p>Wargame Score: {userInfo.fieldScores.WARGAME}</p>
              <p>Solved Problems:</p>
              <ul>
                {userInfo.solvedProblem.map((problem, index) => (
                  <li key={index}>{problem}</li>
                ))}
              </ul>
              <p>Account Created: {new Date(userInfo.created).toLocaleString()}</p>
              <p>Last Active: {new Date(userInfo.lastActived).toLocaleString()}</p>
            </>
          ) : (
            <p>Failed to fetch user data.</p>
          )}
        </div>
        <div className={styles.modalFooter}>
          <h3>Modal Footer</h3>
        </div>
      </div>
    </div>
  );
};

export default Modal;
